            <ValidationMessage For="() => Model.PreferredDoctor" />
            @if (_serverErrors.ContainsKey("PreferredDoctor"))
            {
                <div class="validation-message">@_serverErrors["PreferredDoctor"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="date" class="form-label">Date</label>
            <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                       @bind-Value:after="OnDateChanged" />
            <ValidationMessage For="() => Model.AppointmentDate" />
        </div>

        <div class="mb-3">
            <label for="timeSlot" class="form-label">Time Slot</label>
            <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in _timeSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.TimeSlot" />
            @if (_serverErrors.ContainsKey("TimeSlot"))
            {
                <div class="validation-message">@_serverErrors["TimeSlot"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="reason" class="form-label">Reason for Visit</label>
            <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" />
            <ValidationMessage For="() => Model.ReasonForVisit" />
        </div>

        <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability">Check Availability</button>
        <button type="submit" class="btn btn-success" disabled="@(!_validated)">Book Appointment</button>
    }
</EditForm>

@if (_booked)
{
    <div class="alert alert-success mt-3">Appointment booked successfully!</div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private bool _showStep2;
    private bool _validated;
    private bool _booked;
    private List<string> _doctors = new();
    private List<string> _timeSlots = new();
    private Dictionary<string, string> _serverErrors = new();
    private EditContext? _editContext;

    protected override async Task OnInitializedAsync()
    {
        _doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        _editContext = new EditContext(Model);
        _editContext.EnableDataAnnotationsValidation();

        if (_editContext.Validate())
        {
            // Only proceed if step 1 fields are valid
            var step1Valid = !_editContext.GetValidationMessages(() => Model.PatientName).Any()
                         && !_editContext.GetValidationMessages(() => Model.Email).Any()
                         && !_editContext.GetValidationMessages(() => Model.Phone).Any()
                         && !_editContext.GetValidationMessages(() => Model.InsuranceProvider).Any();

            if (step1Valid)
            {
                _showStep2 = true;
            }
        }
        else
        {
            // Check only step 1 fields
            var step1Valid = !_editContext.GetValidationMessages(() => Model.PatientName).Any()
                         && !_editContext.GetValidationMessages(() => Model.Email).Any()
                         && !_editContext.GetValidationMessages(() => Model.Phone).Any()
                         && !_editContext.GetValidationMessages(() => Model.InsuranceProvider).Any();

            if (step1Valid)
            {
                _showStep2 = true;
            }
        }
    }

    private async Task OnDoctorChanged()
    {
        await LoadTimeSlots();
    }

    private async Task OnDateChanged()
    {
        await LoadTimeSlots();
    }

    private async Task LoadTimeSlots()
    {
        if (!string.IsNullOrEmpty(Model.PreferredDoctor) && Model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.PreferredDoctor,
                DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
        else
        {
            _timeSlots = new();
        }

        Model.TimeSlot = string.Empty;
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _validated = false;

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.PreferredDoctor ?? string.Empty,
            Model.TimeSlot ?? string.Empty);

        if (errors.Count > 0)
        {
            _serverErrors = errors;
        }
        else
        {
            _validated = true;
        }
    }

    private void HandleSubmit()
    {
        if (_validated)
        {
            _booked = true;
        }
    }
}
"}

{"path": "/tmp/sv-c4706bea4aaa47d69150893e67ed1f04/Components/Pages/AppointmentModel.cs", "file_text": "using System.ComponentModel.DataAnnotations;

namespace sv_c4706bea4aaa47d69150893e67ed1f04.Components.Pages;

public class AppointmentModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required")]
    [EmailAddress(ErrorMessage = "Invalid email format")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone is required")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Insurance provider is required")]
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2
    [Required(ErrorMessage = "Preferred doctor is required")]
    public string? PreferredDoctor { get; set; }

    [Required(ErrorMessage = "Date is required")]
    [FutureDate(ErrorMessage = "Date must be in the future")]
    public DateTime? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Time slot is required")]
    public string? TimeSlot { get; set; }

    [Required(ErrorMessage = "Reason for visit is required")]
    [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters")]
    public string? ReasonForVisit { get; set; }
}

public class FutureDateAttribute : ValidationAttribute
{
    protected override ValidationResult? IsValid(object? value, ValidationContext validationContext)
    {
        if (value is DateTime date)
        {
            if (date.Date <= DateTime.Today)
            {
                return new ValidationResult(ErrorMessage);
            }
        }
        return ValidationResult.Success;
    }
}
"}

